<?php
namespace App\Http\Controllers;use App\Models\{Drug,DrugBatch,InventoryMovement};use Illuminate\Http\Request;use Illuminate\Support\Facades\{Auth,DB};use Inertia\Inertia;
class InventoryController extends Controller{
 public function index(){return Inertia::render('Hospital/Inventory',['drugs'=>Drug::orderBy('brand_name')->get(['id','brand_name','brand_name_fa','stock_quantity','reorder_level']),'batches'=>DrugBatch::with('drug:id,brand_name')->orderBy('expires_at')->get(),'movements'=>InventoryMovement::with('drug:id,brand_name')->latest()->limit(100)->get()]);}
 public function batch(Request $r){$d=$r->validate(['drug_id'=>'required|exists:drugs,id','batch_number'=>'required|string|max:100','expires_at'=>'required|date_format:Y/m/d','quantity_received'=>'required|integer|min:1','purchase_price'=>'required|integer|min:0','sale_price'=>'required|integer|min:0']);DB::transaction(function()use($d){$batch=DrugBatch::create($d+['quantity_available'=>$d['quantity_received']]);$batch->drug()->increment('stock_quantity',$d['quantity_received']);InventoryMovement::create(['drug_id'=>$d['drug_id'],'drug_batch_id'=>$batch->id,'type'=>'receive','quantity'=>$d['quantity_received'],'reason'=>'دریافت محموله','user_id'=>Auth::id()]);});return back();}
 public function movement(Request $r){$d=$r->validate(['drug_batch_id'=>'required|exists:drug_batches,id','type'=>'required|in:return,waste,adjustment','quantity'=>'required|integer|min:1','reason'=>'required|string|max:255']);DB::transaction(function()use($d){$b=DrugBatch::lockForUpdate()->findOrFail($d['drug_batch_id']);$delta=$d['type']==='return'?$d['quantity']:-$d['quantity'];abort_if($b->quantity_available+$delta<0,422,'موجودی محموله کافی نیست.');$b->increment('quantity_available',$delta);$b->drug()->increment('stock_quantity',$delta);InventoryMovement::create($d+['drug_id'=>$b->drug_id,'quantity'=>$delta,'user_id'=>Auth::id()]);});return back();}
}
